# фон: сумма «За 1 день» по группам с вердиктом «игнорировать»
def num(x):
    try:
        return int(str(x).replace(" ", "") or 0)
    except Exception:
        return 0
newv = {k: v[0] for k, v in V.items()}
bg = 0
tot = 0
for r in vals[1:]:
    rr = r + [""] * 14
    d1 = num(rr[3])
    tot += d1
    verd = newv.get(rr[0].strip(), (rr[8] or "").strip())
    if verd == "игнорировать":
        bg += d1
print("TOTAL d1:", tot, "| BACKGROUND (игнорировать) d1:", bg)
